# Builds the girls' edition (星愿魔法少女) from the shared game source.
import re,sys
SRC='/home/claude/numgate/index.html'
OUT=sys.argv[1] if len(sys.argv)>1 else '/home/claude/numgate/girl.html'
s=open(SRC).read()
def must(a,b,count=None):
  global s
  n=s.count(a)
  if n==0 or (count is not None and n!=count):raise SystemExit('replace failed (%d): %r'%(n,a[:70]))
  s=s.replace(a,b)
XR=['凡人','炼体','炼气','筑基','金丹','元婴','化神','炼虚','合体','大乘','渡劫','真仙','金仙','太乙','大罗','混元','准圣','圣人']
