must("const rName=x=>x.r===0?'凡人':REALMS[x.r]+LAYERS[x.layer-1]+'层';","const rName=x=>x.r===0?'平凡少女':REALMS[x.r]+' '+x.layer+'星';",1)
must('<title>御剑斩妖录</title>','<title>星愿魔法少女</title>\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=ZCOOL+KuaiLe&display=swap" media="print" onload="this.media=\'all\'">',1)
must('<h1 class="ttl">御剑<br>斩妖录</h1>','<h1 class="ttl">星愿<br>魔法少女</h1>',2)
must('<strong>左道 · 修炼</strong>撞上丹药、剑诀、法宝涨修为、变强；避开心魔这类坏门。','<strong>左边 · 收集</strong>撞上星光糖、魔法书、魔法道具，魔力变强、解锁新衣装；避开负能量这类坏门。',1)
must('<strong>右道 · 斩妖</strong>妖魔冲过红线会吸走修为。打死它们也能涨修为。每隔一阵会来一波妖潮。','<strong>右边 · 净化</strong>坏情绪小怪冲过红线会吸走魔力。用星光把它们净化成小花，还能涨魔力。每隔一阵会来一波噩梦潮。',1)
for a,b in [('<span class="ic">🔔</span>','<span class="ic">🫧</span>'),('<span class="ic">📜</span>','<span class="ic">🌙</span>'),('<span class="ic">⚡</span>','<span class="ic">🌈</span>'),('<span class="ic">🌩</span>','<span class="ic">✨</span>'),("'🌩 雷劫符！'","'✨ 星光爆发！'"),("'💣 天雷！'","'✨ 爆发！'"),("dText('⚡'","dText('🌈'")]:must(a,b)
